let navHistory=[];
async function go(id,opts={}){
  const current=document.querySelector('.page:not(.hide)')?.id;
  if(!opts.fromBack && current && current!==id){
    navHistory.push({id:current,scrollY:window.scrollY||window.pageYOffset||0});
  }
  stopAllTutorialMedia();document.querySelectorAll('.page').forEach(p=>p.classList.add('hide'));
  const target=$(id);if(!target)return;target.classList.remove('hide');$('nav').classList.remove('open');
  const restoreY=Number.isFinite(opts.restoreScrollY)?opts.restoreScrollY:0;
  requestAnimationFrame(()=>window.scrollTo(0,restoreY));
  if(id==='winners')await loadWinners();if(id==='tutorial')await loadSettings();if(id==='schedule')await loadSchedule();if(id==='admin')await loadAdmin();if(id==='notifications')await loadNotificationsPage();
}
function goBack(){
  const previous=navHistory.pop();
  if(previous && previous.id) go(previous.id,{fromBack:true,restoreScrollY:previous.scrollY||0});
  else go('home',{fromBack:true,restoreScrollY:0});
}
document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>b.classList.contains('back')?goBack():go(b.dataset.go));document.querySelectorAll('.back').forEach(b=>b.onclick=goBack);document.addEventListener('click',e=>{const b=e.target.closest('[data-tab-jump]');if(!b)return;const tab=document.querySelector(`[data-tab="${b.dataset.tabJump}"]`);if(tab)tab.click();});$('menuBtn').onclick=()=>$('nav').classList.toggle('open');
