// ADMIN SECTION NAVIGATION — every tab opens its matching panel.
function openAdminTab(tabId){
  const tabs=document.querySelectorAll('.adminTabs [data-tab]');
  const panes=document.querySelectorAll('#admin .tabPane');
  const target=document.getElementById(tabId);
  if(!target)return;
  tabs.forEach(btn=>btn.classList.toggle('active',btn.dataset.tab===tabId));
  panes.forEach(p=>p.classList.toggle('hide',p.id!==tabId));
  requestAnimationFrame(()=>{target.scrollIntoView({behavior:'smooth',block:'start'});});
  if(tabId==='notificationsTab') loadNotifications();
  if(tabId==='workTab') loadWorkAdmin();
  if(tabId==='notesAdminTab') loadAdminNotes();
  if(tabId==='groupChatAdminTab'){ renderGroupAdminChat(); stopPrivateTimers(); groupAdminTimer=setInterval(()=>{if(!document.hidden)renderGroupAdminChat()},3500); }
}
document.querySelectorAll('.adminTabs [data-tab]').forEach(btn=>btn.addEventListener('click',()=>openAdminTab(btn.dataset.tab)));
// Let vertical wheel/touch scrolling belong to the page. Only consume a wheel event when a nested rail can actually scroll in that direction.
document.querySelectorAll('.tableScroller,.chatMessages,.notesList,.notificationList,.tabs').forEach(el=>{
  el.addEventListener('wheel',e=>{
    const horizontal=Math.abs(e.deltaX)>Math.abs(e.deltaY);
    if(!horizontal)return;
    const max=el.scrollWidth-el.clientWidth, pos=el.scrollLeft, delta=e.deltaX;
    if(max>0 && ((delta<0&&pos>0)||(delta>0&&pos<max))) e.stopPropagation();
  },{passive:true});
});
