$('roomForm').onsubmit=async e=>{e.preventDefault();if(!dbReady())return;const code=$('roomTracking').value.trim().toUpperCase().replace(/\s+/g,''),box=$('roomResult');box.classList.add('hide');if(!code)return showModal('CHECK FORM','ENTER TRACKING CODE','Please enter your NALOX tracking code.');const statusRes=await sb.rpc('nalox_check_status',{p_tracking_code:code});if(statusRes.error)return showModal('ERROR','ACCESS CHECK FAILED',statusRes.error.message);const player=Array.isArray(statusRes.data)?statusRes.data[0]:statusRes.data;if(!player)return showModal('NOT FOUND','TRACKING CODE NOT FOUND','This tracking code is not registered. Check the full code from your registration success message and try again.');if(String(player.status||'').toLowerCase()==='rejected')return showModal('ACCESS BLOCKED','REGISTRATION REJECTED','This registration has been rejected and cannot access the tournament room.');const {data,error}=await sb.rpc('nalox_check_room_access',{p_tracking_code:code});if(error)return showModal('ERROR','ROOM CHECK FAILED',error.message);const rooms=Array.isArray(data)?data.filter(Boolean):data?[data]:[];if(!rooms.length){box.innerHTML=`<div class="releaseBadge waiting">● NO TOURNAMENT RELEASED</div><h3>Your registration is approved.</h3><p class="accessNote">No tournament room has been released for players yet. Please check again after the admin shows a tournament.</p>`;box.classList.remove('hide');return;}const visibleRooms=rooms.filter(x=>x.released).sort((a,b)=>{const ta=new Date(`${a.event_date||''}T${String(a.event_time||'00:00:00').length===5?String(a.event_time||'00:00:00')+':00':String(a.event_time||'00:00:00')}`).getTime();const tb=new Date(`${b.event_date||''}T${String(b.event_time||'00:00:00').length===5?String(b.event_time||'00:00:00')+':00':String(b.event_time||'00:00:00')}`).getTime();return (Number.isFinite(ta)?ta:Infinity)-(Number.isFinite(tb)?tb:Infinity);});if(!visibleRooms.length){box.innerHTML=`<div class="releaseBadge waiting">● NO TOURNAMENT RELEASED</div><h3>Your registration is approved.</h3><p class="accessNote">Tournament details are saved by the admin but no room is currently released. Check again when it is shown.</p>`;box.classList.remove('hide');return;}box.innerHTML='<div class="roomTournamentGrid">'+visibleRooms.map((r,i)=>{const idVisible=r.room_id_visible===true&&!!r.room_id;const passVisible=r.room_password_visible===true&&!!r.room_password;const date=String(r.event_date||'');const time=String(r.event_time||'00:00:00');const countdownDate=date?`${date}T${time.length===5?time+':00':time}`:'';return `<article class="tournamentRoomCard roomTournamentCompact"><div class="roomTournamentTitleRow"><img class="tournamentRoomImage" src="${esc(r.image_url||'nalox-logo.jpg')}" alt="Tournament logo"><div class="roomTournamentTitle"><span class="releaseBadge">● ROOM ACCESS RELEASED</span><h3>${esc(r.tournament_name||`Tournament ${i+1}`)}</h3><span class="tournamentNo">TOURNAMENT #${i+1}</span></div></div><div class="roomTournamentCountdown"><small>TIME LEFT TO MATCH</small><strong data-countdown-date="${esc(countdownDate)}">Calculating…</strong></div><div class="accessGrid"><div><small>DATE</small><b>${fmtDate(r.event_date)}</b></div><div><small>TIME</small><b>${esc(tournamentTime12h(r.event_time))}</b></div><div><small>ROOM ID</small><b>${idVisible?esc(r.room_id):'HIDDEN'} ${idVisible?`<button class="copyMini" data-copy="${esc(r.room_id)}" aria-label="Copy Room ID">COPY ID</button>`:''}</b></div><div><small>ROOM PASSWORD</small><b>${passVisible?esc(r.room_password):'HIDDEN'} ${passVisible?`<button class="copyMini" data-copy="${esc(r.room_password)}" aria-label="Copy Room Password">COPY PASSWORD</button>`:''}</b></div><div><small>PRIZE</small><b>${money(r.prize_amount)}</b></div></div><button type="button" class="copyRoomAll" data-copy-all="${esc(`Tournament: ${r.tournament_name||`Tournament ${i+1}`}\nDate: ${fmtDate(r.event_date)}\nTime: ${tournamentTime12h(r.event_time)}\nPrize: ${money(r.prize_amount)}\nRoom ID: ${idVisible?r.room_id:'Not released'}\nRoom Password: ${passVisible?r.room_password:'Not released'}`)}">COPY ALL DETAILS</button></article>`}).join('')+'</div>';box.classList.remove('hide');refreshScheduleCountdowns();if(scheduleCountdownTimer)clearInterval(scheduleCountdownTimer);scheduleCountdownTimer=setInterval(refreshScheduleCountdowns,1000);box.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);const old=b.textContent;b.textContent='COPIED ✓';setTimeout(()=>b.textContent=old,1200)}catch{showModal('COPY FAILED','COULD NOT COPY','Please copy the value manually.')}});box.querySelectorAll('[data-copy-all]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copyAll);b.textContent='COPIED ALL ✓';setTimeout(()=>b.textContent='COPY ALL DETAILS',1400)}catch{showModal('COPY FAILED','COULD NOT COPY','Please copy the details manually.')}})};
let scheduleCountdownTimer=null;
function tournamentTime12h(value){if(!value)return 'Time TBA';const parts=String(value).slice(0,8).split(':');if(parts.length<2)return String(value);const d=new Date();d.setHours(Number(parts[0])||0,Number(parts[1])||0,Number(parts[2])||0,0);return d.toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit',hour12:true});}
function refreshScheduleCountdowns(){document.querySelectorAll('[data-countdown-date]').forEach(el=>{const raw=el.dataset.countdownDate;const target=new Date(raw).getTime();if(!Number.isFinite(target)){el.textContent='Countdown unavailable';return;}let diff=target-Date.now();if(diff<=0){el.textContent='MATCH TIME REACHED';el.classList.add('countdownLive');return;}const days=Math.floor(diff/86400000);diff%=86400000;const hours=Math.floor(diff/3600000);diff%=3600000;const mins=Math.floor(diff/60000);const secs=Math.floor((diff%60000)/1000);el.textContent=`${days?days+'d ':''}${String(hours).padStart(2,'0')}h ${String(mins).padStart(2,'0')}m ${String(secs).padStart(2,'0')}s`;});}
async function loadSchedule(){
  const box=$('scheduleList'); if(!box)return;
  if(scheduleCountdownTimer){clearInterval(scheduleCountdownTimer);scheduleCountdownTimer=null;}
  if(!dbReady()){box.innerHTML='<div class="empty">Tournament schedule is unavailable until Supabase is connected.</div>';return;}
  // Try the full schema, then gracefully fall back if optional columns are not present.
  let {data,error}=await sb.from('tournament_access').select('id,tournament_name,event_date,event_time,prize_amount,released,is_completed,image_url').order('event_date',{ascending:true}).order('event_time',{ascending:true});
  if(error && /image_url|is_completed|column|schema cache|could not find/i.test(String(error.message||''))){
    const fallback=await sb.from('tournament_access').select('id,tournament_name,event_date,event_time,prize_amount,released,is_completed').order('event_date',{ascending:true}).order('event_time',{ascending:true});
    data=fallback.data;error=fallback.error;
    if(error && /is_completed|column|schema cache|could not find/i.test(String(error.message||''))){
      const legacy=await sb.from('tournament_access').select('id,tournament_name,event_date,event_time,prize_amount,released').order('event_date',{ascending:true}).order('event_time',{ascending:true});
      data=legacy.data;error=legacy.error;
    }
  }
  if(error){console.error('Tournament schedule load failed:',error);box.innerHTML=`<div class="empty"><b>Could not load tournament schedule.</b><p>${esc(error.message||'Supabase returned an unknown error.')}</p><p>Check Supabase connection, table permissions, and the tournament_access table schema.</p></div>`;return;}
  const rows=(data||[]).filter(r=>r.is_completed!==true).sort((a,b)=>{
    const stamp=r=>{const d=String(r.event_date||''),t=String(r.event_time||'00:00:00');const n=Date.parse(d?`${d}T${t.length===5?t+':00':t}`:'');return Number.isFinite(n)?n:Infinity};return stamp(a)-stamp(b);
  });
  box.innerHTML=rows.length?rows.map((r,i)=>{const date=String(r.event_date||'');const time=String(r.event_time||'00:00:00');const countdownDate=date?`${date}T${time.length===5?time+':00':time}`:'';return `<article class="scheduleItem"><div class="scheduleNo">#${i+1}</div><img class="scheduleTournamentLogo" src="${esc(r.image_url||'nalox-logo.jpg')}" alt="${esc(r.tournament_name||'Tournament')} logo" loading="lazy" onerror="this.onerror=null;this.src='nalox-logo.jpg'"><div class="scheduleMain"><p class="kicker">UPCOMING TOURNAMENT</p><h3>${esc(r.tournament_name||'CLUTCH ZONE')}</h3><div class="scheduleMeta"><span>📅 ${esc(fmtDate(r.event_date))}</span><span>⏰ ${esc(tournamentTime12h(r.event_time))}</span><span>🏆 ${money(r.prize_amount)}</span></div><div class="scheduleCountdownWrap"><small>TIME LEFT TO MATCH</small><strong class="scheduleCountdown" data-countdown-date="${esc(countdownDate)}">Calculating…</strong></div><button type="button" class="scheduleRoomLink" data-open-room-access>VIEW ID / PASSWORD ↗</button></div><span class="releaseBadge">SCHEDULED</span></article>`}).join(''):'<div class="empty">No upcoming tournaments right now. Check again later.</div>';
  box.querySelectorAll('[data-open-room-access]').forEach(btn=>btn.addEventListener('click',()=>go('roomAccess')));
  refreshScheduleCountdowns();scheduleCountdownTimer=setInterval(refreshScheduleCountdowns,1000);
}
async function loadWinners(){if(!dbReady())return;const {data,error}=await sb.from('winners').select('id,player_name,ff_uid,country_name,country_code,prize_amount,is_visible,created_at').eq('is_visible',true).order('created_at',{ascending:false});if(error)return $('winnerList').innerHTML='<div class="empty">Could not load winners.</div>';winners=data||[];$('winnerList').innerHTML=winners.length?winners.map((w,i)=>`<article class="winnerCard"><span class="rank">#${i+1} WINNER</span><h3>${esc(w.player_name)}</h3><p>UID • ${esc(w.ff_uid)}</p><p>${flag(w.country_code)} ${esc(w.country_name)}</p><strong>${money(w.prize_amount)}</strong></article>`).join(''):'<div class="empty">No winners announced yet.</div>'}
async function loadSettings(){if(!dbReady())return;
  const {data,error}=await sb.from('tutorial_videos').select('id,title,video_url,video_type,thumbnail_url,entry_url,is_visible,created_at').order('created_at',{ascending:false});
  if(error){console.error(error);tutorialVideos=[];appDownloadUrl='';}else{const rows=data||[];const appRow=rows.find(v=>v.video_type==='app_download'||v.title==='__NALOX_APP_DOWNLOAD__');appDownloadUrl=appRow?.video_url||'https://www.mediafire.com/file/gn9m8uivuij59t6/ClutchZONE.apk/file?dkey=x8bwofbbotn&r=1586';tutorialVideos=rows.filter(v=>v!==appRow);}
  renderTutorialAdminList();
  if($('appDownloadUrl'))$('appDownloadUrl').value=appDownloadUrl;
  renderTutorials();
}
function youtubeId(url){const m=String(url||'').match(/(?:youtube\.com\/(?:watch\?v=|embed\/|shorts\/)|youtu\.be\/)([A-Za-z0-9_-]{6,})/i);return m?m[1]:null}
// Fullscreen controls intentionally removed; videos use their natural aspect ratio.
function renderTutorials(){const w=$('videoWrap');if(!w)return;const feature=FEATURED_TUTORIAL;const featuredMedia=()=>{const yt=youtubeId(feature.src);return yt?`<div class="videoStage"><iframe src="https://www.youtube.com/embed/${yt}?playsinline=1" title="${esc(feature.title)}" allow="autoplay; encrypted-media" loading="lazy"></iframe></div>`:`<div class="videoStage"><video controls playsinline webkit-playsinline preload="metadata" src="${esc(feature.src)}"></video></div>`};
 const mediaFor=(v,isFeatured=false)=>{const yt=youtubeId(v.video_url),thumb=v.thumbnail_url||'';if(yt&&!isFeatured&&thumb)return `<button class="videoThumb" type="button" data-play-youtube="${esc(yt)}" aria-label="Play tutorial"><img src="${esc(thumb)}" alt="Tutorial thumbnail"><span>▶</span></button>`;return yt?`<div class="videoStage"><iframe src="https://www.youtube.com/embed/${yt}?playsinline=1" title="${esc(v.title||'NALOX tutorial')}" allow="autoplay; encrypted-media" loading="lazy"></iframe></div>`:`<div class="videoStage"><video controls playsinline webkit-playsinline preload="metadata" ${thumb?`poster="${esc(thumb)}"`:''} src="${esc(v.video_url)}"></video></div>`};
 const rest=tutorialVideos.filter(v=>v.is_visible!==false);
 w.innerHTML=`<section class="tutorialCard featuredTutorial"><span class="featuredBadge">★ FEATURED • WATCH FIRST</span><div class="tutorialTitle"><span>01</span><h3>${esc(feature.title)}</h3></div>${featuredMedia()}${feature.entryUrl&&feature.entryUrl!=='https://YOUR-WEBSITE-LINK-HERE.com'?`<a class="tutorialWebsiteLink" href="${esc(feature.entryUrl)}" target="_blank" rel="noopener">OPEN WEBSITE ↗</a>`:''}${appDownloadUrl?`<a class="tutorialAppLink" href="#" data-app-download="${esc(appDownloadUrl)}">DOWNLOAD APP ↓</a>`:''}</section>${rest.length?`<div class="tutorialRestHead"><span>MORE TUTORIALS</span><small>${rest.length} VIDEO${rest.length===1?'':'S'}</small></div><div class="tutorialGrid">${rest.map((v,i)=>`<article class="tutorialCard"><div class="tutorialTitle"><span>${String(i+2).padStart(2,'0')}</span><h3>${esc(v.title||'NALOX Tutorial')}</h3></div>${mediaFor(v)}<a class="tutorialWebsiteLink" href="${TUTORIAL_WEBSITE_URL}" target="_blank" rel="noopener">OPEN WEBSITE ↗</a>${appDownloadUrl?`<a class="tutorialAppLink" href="#" data-app-download="${esc(appDownloadUrl)}">DOWNLOAD APP ↓</a>`:''}${v.video_url?`<div class="tutorialSource">${youtubeId(v.video_url)?'YOUTUBE':'MP4 VIDEO'}</div>`:''}</article>`).join('')}</div>`:''}`;
 w.querySelectorAll('[data-play-youtube]').forEach(btn=>btn.onclick=()=>{const id=btn.dataset.playYoutube;const stage=document.createElement('div');stage.className='videoStage';stage.innerHTML=`<iframe src="https://www.youtube.com/embed/${id}?autoplay=1&playsinline=1" title="NALOX tutorial" allow="autoplay; encrypted-media" loading="lazy"></iframe>`;btn.replaceWith(stage)});
 
}
function renderVideo(url){const w=$('videoWrap');if(!url)return w.innerHTML='<div class="empty">Tutorial video will appear here.</div>';const yt=url.match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|embed\/|shorts\/))([\w-]{6,})/i);if(yt)w.innerHTML=`<div class="videoStage"><iframe src="https://www.youtube.com/embed/${yt[1]}" title="NALOX tutorial" allow="autoplay; encrypted-media" loading="lazy"></iframe></div>`;else w.innerHTML=`<div class="videoStage"><video controls playsinline webkit-playsinline preload="metadata" src="${esc(url)}"></video></div>`;}

document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAllTutorialMedia()});window.addEventListener('pagehide',stopAllTutorialMedia);window.addEventListener('beforeunload',stopAllTutorialMedia);window.addEventListener('popstate',stopAllTutorialMedia);

// App download: MediaFire shared pages cannot be embedded reliably because providers may block framing.
function openAppDownload(url){
  if(!url)return;
  const modal=$('mediafireModal'),fallback=$('mediafireFallback');
  fallback.href=url;
  fallback.setAttribute('download','');
  $('copyAppLink').onclick=async()=>{try{await navigator.clipboard.writeText(url);$('copyAppLink').textContent='COPIED ✓';setTimeout(()=>$('copyAppLink').textContent='COPY DOWNLOAD LINK',1200)}catch{}};
  modal.classList.remove('hide');
}
document.addEventListener('click',e=>{const a=e.target.closest('[data-app-download]');if(!a)return;e.preventDefault();openAppDownload(a.dataset.appDownload)});
$('closeMediafire').onclick=()=>{$('mediafireModal').classList.add('hide')};
$('mediafireModal').onclick=e=>{if(e.target===$('mediafireModal'))$('closeMediafire').click()};

$('loginForm').onsubmit=async e=>{e.preventDefault();if(!dbReady())return;const {data,error}=await sb.auth.signInWithPassword({email:$('adminEmail').value.trim(),password:$('adminPass').value});if(error)return showModal('DENIED','LOGIN FAILED',error.message);session=data.session;if(await isAdmin())go('admin');else{await sb.auth.signOut();showModal('DENIED','NOT AN ADMIN','This account is not authorized.')}};
async function isAdmin(){if(!session)return false;const {data,error}=await sb.from('admin_roles').select('role').eq('user_id',session.user.id).eq('role','admin').maybeSingle();return !error&&!!data}
$('logout').onclick=async()=>{await sb.auth.signOut();session=null;go('home')};
async function loadAdmin(){if(!dbReady())return;if(!await isAdmin())return go('adminLogin');const [r,w,a,t]=await Promise.all([sb.from('tournament_requests').select('id,tracking_code,ff_name,ff_uid,country_name,country_code,mobile_number,status,created_at').order('created_at',{ascending:true}),sb.from('winners').select('id,player_name,ff_uid,country_name,country_code,prize_amount,is_visible,created_at').order('created_at',{ascending:false}),sb.from('tournament_access').select('*').order('updated_at',{ascending:false}),sb.from('tutorial_videos').select('id,title,video_url,video_type,thumbnail_url,entry_url,is_visible,created_at').order('created_at',{ascending:false})]);if(r.error||w.error||a.error||t.error)return showModal('ERROR','ADMIN DATA FAILED',(r.error||w.error||a.error||t.error).message);requests=r.data||[];winners=w.data||[];roomAccessRows=a.data||[];tutorialVideos=t.data||[];$('statAll').textContent=requests.length;$('statPending').textContent=requests.filter(x=>x.status==='Pending').length;$('statWinners').textContent=winners.length;renderRequests();renderAdminWinners();renderRoomAdmin();renderTutorialAdminList();renderTutorials();loadGlobalRoomForm()}
