$('roomAdminList').onclick=async e=>{const complete=e.target.closest('[data-complete-room]'),edit=e.target.closest('[data-editglobal]'),toggle=e.target.closest('[data-toggle-room]'),del=e.target.closest('[data-delete-room]');if(complete){const a=roomAccessRows.find(x=>x.id===complete.dataset.completeRoom);if(!a)return;confirmDelete('APPROVE COMPLETED TOURNAMENT?',`<div><span>TOURNAMENT</span><b>${esc(a.tournament_name||'Tournament')}</b></div><div><span>RESULT</span><b>This match will be removed from the public Match Schedule.</b></div>`,async()=>{const {error}=await sb.from('tournament_access').update({is_completed:true,released:false}).eq('id',a.id);if(error)return showModal('ERROR','TOURNAMENT NOT UPDATED',error.message);await loadAdmin();await loadSchedule();showModal('SUCCESS','TOURNAMENT COMPLETED','Approved as completed and removed from Match Schedule.')});return}if(edit){const a=roomAccessRows.find(x=>x.id===edit.dataset.editglobal);if(a){fillGlobalAccessForm(a);document.querySelector('[data-tab="roomTab"]').click();requestAnimationFrame(()=>document.getElementById('roomAdminForm')?.scrollIntoView({behavior:'smooth',block:'start'}))}return}if(toggle){const a=roomAccessRows.find(x=>x.id===toggle.dataset.toggleRoom);if(!a)return;const {error}=await sb.from('tournament_access').update({released:!a.released}).eq('id',a.id);if(error)return showModal('ERROR','VISIBILITY UPDATE FAILED',error.message);await loadAdmin();showModal('SUCCESS',a.released?'TOURNAMENT HIDDEN':'TOURNAMENT SHOWN',a.released?'The tournament is hidden from players.':'The tournament is now visible to approved players.');return}if(del){const a=roomAccessRows.find(x=>x.id===del.dataset.deleteRoom);if(!a)return;confirmDelete('DELETE TOURNAMENT PERMANENTLY?',`<div><span>TOURNAMENT</span><b>${esc(a.tournament_name||'Tournament')}</b></div><div><span>DATE</span><b>${esc(a.event_date||'Not set')}</b></div><div><span>ROOM ID</span><b>${esc(a.room_id||'Not set')}</b></div>`,async()=>{const {error}=await sb.from('tournament_access').delete().eq('id',a.id);if(error)return showModal('ERROR','DELETE FAILED',error.message);await loadAdmin();resetRoomForm();showModal('SUCCESS','TOURNAMENT DELETED','The tournament was permanently removed.')});return}};
if($('addNewTournament'))$('addNewTournament').onclick=()=>{resetRoomForm();requestAnimationFrame(()=>document.getElementById('roomTournamentName')?.focus())};
$('accessEditForm').onsubmit=async e=>{e.preventDefault();const id=$('accessEditId').value,p={tournament_name:$('accessEditTournament').value.trim(),room_id:$('accessEditRoomId').value.trim(),room_password:$('accessEditRoomPassword').value.trim(),event_date:$('accessEditDate').value,event_time:$('accessEditTime').value,prize_amount:Number($('accessEditPrize').value||0),released:$('accessEditReleased').checked,room_id_visible:$('accessEditRoomIdVisible').checked,room_password_visible:$('accessEditRoomPasswordVisible').checked};const {error}=await sb.from('tournament_access').update(p).eq('id',id);if(error)return showModal('ERROR','ROOM SAVE FAILED',error.message);closeAccessEditor();await loadAdmin();showModal('SUCCESS',p.released?'ROOM ACCESS RELEASED':'ROOM DETAILS SAVED',p.released?'The live room is now available to approved players.':'Room details updated.')};
const thumbnailFile=$('thumbnailFile'),thumbnailPreview=$('thumbnailPreview');
thumbnailFile.onchange=()=>{const f=thumbnailFile.files?.[0];if(!f){thumbnailPreview.innerHTML='<img src="nalox-logo.jpg" alt="Default CLUTCH ZONE logo"><span>DEFAULT WEBSITE LOGO</span>';return}if(!f.type.startsWith('image/')){thumbnailFile.value='';return showModal('CHECK FILE','IMAGE REQUIRED','Please select an image thumbnail.')}const u=URL.createObjectURL(f);thumbnailPreview.innerHTML=`<img src="${u}" alt="Thumbnail preview"><span>${esc(f.name)}</span>`};
async function uploadThumbnail(file){if(!file)return null;const ext=(file.name.split('.').pop()||'jpg').replace(/[^a-z0-9]/gi,'').toLowerCase()||'jpg',path=`tutorial/thumb-${Date.now()}-${Math.random().toString(36).slice(2,8)}.${ext}`;const {error}=await sb.storage.from('tutorial-thumbnails').upload(path,file,{cacheControl:'3600',upsert:false,contentType:file.type||'image/jpeg'});if(error)throw error;const {data}=sb.storage.from('tutorial-thumbnails').getPublicUrl(path);return data?.publicUrl||null}
async function addTutorialRow(url,type,thumbnailUrl){const {error}=await sb.from('tutorial_videos').insert({title:'NALOX Tutorial',video_url:url,video_type:type||'video',thumbnail_url:thumbnailUrl||null,entry_url:null,is_visible:true});if(error)throw error;await loadSettings();}
$('settingsForm').onsubmit=async e=>{e.preventDefault();const url=$('videoUrl').value.trim(),thumb=thumbnailFile.files?.[0];if(!url)return showModal('CHECK FORM','VIDEO LINK REQUIRED','Paste a YouTube video link or direct MP4 link.');if(!/^https?:\/\//i.test(url))return showModal('CHECK LINK','VALID LINK REQUIRED','Use a full YouTube or MP4 link starting with http:// or https://');if(!session||!await isAdmin())return showModal('DENIED','ADMIN REQUIRED','Please login as admin.');const btn=e.submitter||$('settingsForm').querySelector('.submit');btn.disabled=true;btn.textContent='SAVING…';try{const thumbnailUrl=thumb?await uploadThumbnail(thumb):'nalox-logo.jpg';await addTutorialRow(url,youtubeId(url)?'youtube':'direct',thumbnailUrl);try{await publishNotification('New tutorial added','A new tutorial video is now available in the Tutorial section.','info')}catch{}showModal('SUCCESS','VIDEO SAVED','Tutorial added separately. Add as many videos as you want.');$('settingsForm').reset();thumbnailPreview.innerHTML='<img src="nalox-logo.jpg" alt="Default CLUTCH ZONE logo"><span>DEFAULT WEBSITE LOGO</span>';}catch(err){console.error(err);showModal('ERROR','VIDEO NOT SAVED',err.message||String(err))}finally{btn.disabled=false;btn.textContent='SAVE VIDEO'}};
$('appDownloadForm').onsubmit=async e=>{e.preventDefault();const url=$('appDownloadUrl').value.trim();if(!/^https?:\/\//i.test(url))return showModal('CHECK LINK','VALID APP LINK REQUIRED','Paste a full APK/app download link starting with http:// or https://');if(!session||!await isAdmin())return showModal('DENIED','ADMIN REQUIRED','Please login as admin.');const btn=e.submitter||$('appDownloadForm').querySelector('.submit');btn.disabled=true;btn.textContent='SAVING…';try{const {data:oldRows,error:findErr}=await sb.from('tutorial_videos').select('id').eq('video_type','app_download');if(findErr)throw findErr;if(oldRows&&oldRows.length){const {error}=await sb.from('tutorial_videos').update({video_url:url,title:'__NALOX_APP_DOWNLOAD__',is_visible:true}).eq('id',oldRows[0].id);if(error)throw error;}else{const {error}=await sb.from('tutorial_videos').insert({title:'__NALOX_APP_DOWNLOAD__',video_url:url,video_type:'app_download',thumbnail_url:null,entry_url:null,is_visible:true});if(error)throw error;}appDownloadUrl=url;renderTutorials();try{await publishNotification('App download updated','The NALOX app download option has been updated.','info')}catch{}showModal('SUCCESS','APP LINK SAVED','DOWNLOAD APP button is now available below tutorial videos.');}catch(err){console.error(err);showModal('ERROR','APP LINK NOT SAVED',err.message||String(err))}finally{btn.disabled=false;btn.textContent='SAVE APP LINK'}};
function renderTutorialAdminList(){
  const box=$('tutorialAdminList');
  if(!box)return;
  box.innerHTML=tutorialVideos.length?tutorialVideos.map((v,i)=>`<div class=\"tutorialAdminRow\"><div><b>${esc(v.title||'NALOX Tutorial')}</b><small>${youtubeId(v.video_url)?'YOUTUBE':'MP4 LINK'} • ${v.is_visible?'VISIBLE':'HIDDEN'}</small></div><button class=\"action gold\" data-tutorial-toggle=\"${v.id}\">${v.is_visible?'HIDE':'SHOW'}</button><button class=\"action bad\" data-tutorial-delete=\"${v.id}\">DELETE</button></div>`).join(''):'<div class=\"empty\">No additional tutorials yet.</div>';
}

$('tutorialAdminList').onclick=async e=>{const tg=e.target.closest('[data-tutorial-toggle]'),del=e.target.closest('[data-tutorial-delete]');if(tg){const v=tutorialVideos.find(x=>x.id===tg.dataset.tutorialToggle);if(v){const {error}=await sb.from('tutorial_videos').update({is_visible:!v.is_visible}).eq('id',v.id);if(error)return showModal('ERROR','UPDATE FAILED',error.message);await loadAdmin();}}if(del){const v=tutorialVideos.find(x=>x.id===del.dataset.tutorialDelete);if(!v)return;confirmDelete('Delete tutorial?',`<div><span>VIDEO</span><b>${esc(v.title)}</b></div>`,async()=>{const {error}=await sb.from('tutorial_videos').delete().eq('id',v.id);if(error)return showModal('ERROR','DELETE FAILED',error.message);await loadAdmin();showModal('SUCCESS','TUTORIAL DELETED','Tutorial removed.')})}};

function getSeenNotificationIds(){try{return JSON.parse(localStorage.getItem("nalox_seen_notifications")||"[]")}catch{return[]}}
function markNotificationsSeen(){const ids=[...document.querySelectorAll("[data-notification-id]")].map(x=>x.dataset.notificationId).filter(Boolean);localStorage.setItem("nalox_seen_notifications",JSON.stringify([...new Set([...getSeenNotificationIds(),...ids])].slice(-200)));const b=$("notifyBadge");if(b){b.textContent="0";b.classList.add("hide")}}
async function loadNotifications(){if(!dbReady())return;const {data,error}=await sb.from('site_notifications').select('id,title,message,type,image_url,created_at').eq('is_visible',true).order('created_at',{ascending:false}).limit(50);if(error){console.error(error);return}const rows=data||[],seen=getSeenNotificationIds();const unread=rows.filter(r=>!seen.includes(r.id)).length;const badge=$('notifyBadge');if(badge){badge.textContent=String(unread);badge.classList.toggle('hide',unread===0)}const render=rows.length?rows.map(r=>`<article class="notificationItem" data-notification-id="${esc(r.id)}"><img class="notificationItemImage" src="${esc(r.image_url||'nalox-logo.jpg')}" alt="NALOX update"><div><span class="notificationType ${esc(r.type||'info')}">${esc(String(r.type||'INFO').toUpperCase())}</span><h4>${esc(r.title)}</h4><p>${esc(r.message)}</p><small>${fmtDate(r.created_at)}</small></div></article>`).join(''):'<div class="empty">No updates yet.</div>';const list=$('notificationList');if(list)list.innerHTML=render;const pageList=$('notificationPageList');if(pageList)pageList.innerHTML=render;const adminList=$('adminNotificationList');if(adminList)adminList.innerHTML=rows.length?rows.map(r=>`<article class="notificationAdminRow"><div class="notificationAdminMedia"><img src="${esc(r.image_url||'nalox-logo.jpg')}" alt=""><div><b>${esc(r.title)}</b><small>${fmtDate(r.created_at)}</small><p>${esc(r.message)}</p></div></div><button class="action bad" data-delete-notification="${esc(r.id)}">DELETE</button></article>`).join(''):'<div class="empty">No published updates.</div>'}
async function loadNotificationsPage(){await loadNotifications();markNotificationsSeen()}
async function uploadNotificationImage(file){if(!file)return 'nalox-logo.jpg';if(!dbReady())throw new Error('Database is not ready.');const ext=(file.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,'')||'jpg';const path=`${crypto.randomUUID()}.${ext}`;const {error}=await sb.storage.from('nalox-notifications').upload(path,file,{upsert:false,contentType:file.type||'image/jpeg'});if(error)throw error;const {data}=sb.storage.from('nalox-notifications').getPublicUrl(path);return data.publicUrl}
async function publishNotification(title,message,type="info",imageFile=null){if(!dbReady())throw new Error("Database is not ready.");const image_url=await uploadNotificationImage(imageFile);const {error}=await sb.from("site_notifications").insert({title:title.trim(),message:message.trim(),type,image_url});if(error)throw error;await loadNotifications()}
$('notificationForm').onsubmit=async e=>{e.preventDefault();if(!session||!await isAdmin())return showModal('DENIED','ADMIN REQUIRED','Please login as admin.');const title=$('notificationTitle').value.trim(),message=$('notificationMessage').value.trim(),type=$('notificationType').value,file=$('notificationImage')?.files?.[0]||null;if(!title||!message)return;const btn=e.submitter||$('notificationForm').querySelector('.submit');btn.disabled=true;btn.textContent='PUBLISHING…';try{await publishNotification(title,message,type,file);$('notificationForm').reset();showModal('SUCCESS','UPDATE PUBLISHED','The update is now visible in the notification bell.')}catch(err){showModal('ERROR','UPDATE NOT SAVED',err.message||String(err))}finally{btn.disabled=false;btn.textContent='PUBLISH UPDATE'}};
$('adminNotificationList').onclick=async e=>{const b=e.target.closest('[data-delete-notification]');if(!b)return;const {error}=await sb.from('site_notifications').delete().eq('id',b.dataset.deleteNotification);if(error)return showModal('ERROR','DELETE FAILED',error.message);await loadNotifications()};

// WORK WITH ME + private chat. Uses the SAME tournament tracking code as Status, ROOM ID PASSWORD and Note Pad.
let workTrackingCode='',workChatTimer=null,adminChatTracking='',adminChatTimer=null,notesTrackingCode='',notesTimer=null,groupTrackingCode='',groupChatTimer=null,groupAdminTimer=null,privateVisitorKey=localStorage.getItem('nalox_private_visitor_key')||crypto.randomUUID();localStorage.setItem('nalox_private_visitor_key',privateVisitorKey);
function normalizeCode(v){return String(v||'').trim().toUpperCase().replace(/\s+/g,'')}
function chatReadKey(code){return 'nalox_admin_chat_read_'+normalizeCode(code)}
function getChatReadAt(code){const value=localStorage.getItem(chatReadKey(code));const parsed=value?Date.parse(value):0;return Number.isFinite(parsed)?parsed:0}
