async function rpcCompat(names,args={}){let last=null;for(const name of names){try{const r=await sb.rpc(name,args);if(!r.error)return r;last=r;}catch(e){last={data:null,error:e}}}return last||{data:null,error:new Error('RPC unavailable')};}
