function avatarLetter(name){return esc(String(name||'U').trim().slice(0,1).toUpperCase()||'U')}
async function renderGroupChat(){
  if(!groupTrackingCode)return;
  const {data,error}=await rpcCompat(['nalox_group_chat_messages'],{p_tracking_code:groupTrackingCode});
  if(error){$('groupChatMessages').innerHTML='<div class="empty">Group chat could not be loaded. Run the latest Supabase group-chat patch.</div>';return}
  const rows=Array.isArray(data)?data:[];
  $('groupChatMessages').innerHTML=rows.length?rows.map(m=>`<div class="groupMsg ${m.is_mine?'mine':''}"><div class="groupAvatar"><span>${avatarLetter(m.sender_name)}</span></div><div class="groupMsgBody"><div class="groupMsgName">${esc(m.sender_name||'PLAYER')}</div><div class="groupMsgBubble">${esc(m.message)}</div><small>${fmtDate(m.created_at)}</small></div></div>`).join(''):'<div class="empty">No group messages yet. Say hello 👋</div>';
  $('groupChatMessages').scrollTop=$('groupChatMessages').scrollHeight;
  const {data:online}=await rpcCompat(['nalox_group_chat_online'],{p_tracking_code:groupTrackingCode});
  $('groupOnlineCount').textContent=`${Number(online?.[0]?.online_count||0)} ONLINE`;
}
async function openGroupChat(code){
  groupTrackingCode=normalizeCode(code);
  if(!groupTrackingCode.startsWith('NALOX_TOURNAMENT_'))return showModal('CHECK CODE','INVALID TRACKING CODE','Use the tournament tracking code from your registration.');
  const {data,error}=await rpcCompat(['nalox_group_chat_join'],{p_tracking_code:groupTrackingCode});
  if(error||!data?.[0])return showModal('NOT FOUND','GROUP CHAT NOT FOUND',error?.message||'This tracking code is not valid.');
  const member=data[0];
  $('groupChatPanel').classList.remove('hide');
  $('groupChatUnlockForm').classList.add('hide');
  $('groupChatIdentity').textContent='TOURNAMENT GROUP';
  $('groupChatMeta').textContent=`${member.ff_name||'PLAYER'} • ${groupTrackingCode}`;
  $('groupMyAvatar').textContent=avatarLetter(member.ff_name);
  await rpcCompat(['nalox_group_chat_heartbeat'],{p_tracking_code:groupTrackingCode,p_visitor_key:privateVisitorKey});
  await renderGroupChat();
  stopPrivateTimers();
  groupChatTimer=setInterval(async()=>{if(document.hidden)return;await rpcCompat(['nalox_group_chat_heartbeat'],{p_tracking_code:groupTrackingCode,p_visitor_key:privateVisitorKey});await renderGroupChat()},3500);
}
