async function loadPublicManagedSections(){
  if(!dbReady())return;
  const {data,error}=await sb.rpc('nalox_public_sections');
  if(error){console.warn('Managed sections unavailable',error);return}
  const box=$('managedSections'); if(!box)return;
  const rows=data||[];
  box.innerHTML=rows.map(r=>`<button class="featureCard" type="button"><div class="featureIcon">${esc(r.icon||'🏆')}</div><div><small>${esc(r.subtitle||'TOURNAMENT INFO')}</small><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p></div><strong>INFO →</strong></button>`).join('');
}
async function loadAdminManagedSections(){
  if(!dbReady()||!await isAdmin())return;
  const {data,error}=await sb.rpc('nalox_admin_sections_list');
  const box=$('sectionAdminList'); if(!box)return;
  if(error){box.innerHTML='<div class="empty">Sections could not be loaded. Run NALOX_CHAT_AND_SECTIONS_PATCH.sql.</div>';return}
  box.innerHTML=(data||[]).map(r=>`<article class="sectionAdminRow"><div class="sectionAdminIcon">${esc(r.icon||'🏆')}</div><div><b>${esc(r.title)}</b><small>${esc(r.section_key)} • ${r.is_visible?'VISIBLE':'HIDDEN'} • ORDER ${Number(r.sort_order||0)}</small><p>${esc(r.description)}</p></div><div class="sectionAdminActions"><button class="action gold" data-section-edit="${r.id}">EDIT</button><button class="action" data-section-toggle="${r.id}" data-visible="${r.is_visible}">${r.is_visible?'HIDE':'SHOW'}</button><button class="action bad" data-section-delete="${r.id}">DELETE</button></div></article>`).join('')||'<div class="empty">No extra sections yet. Add useful tournament information above.</div>';
  box._rows=data||[];
}
