if($('sectionAdminList'))$('sectionAdminList').onclick=async e=>{const rows=e.currentTarget._rows||[];const edit=e.target.closest('[data-section-edit]'),toggle=e.target.closest('[data-section-toggle]'),del=e.target.closest('[data-section-delete]');if(edit){const r=rows.find(x=>String(x.id)===edit.dataset.sectionEdit);if(!r)return;$('sectionId').value=r.id;$('sectionKey').value=r.section_key||'';$('sectionTitle').value=r.title||'';$('sectionIcon').value=r.icon||'🏆';$('sectionSubtitle').value=r.subtitle||'';$('sectionDescription').value=r.description||'';$('sectionOrder').value=r.sort_order||0;$('sectionVisible').checked=!!r.is_visible;$('cancelSectionEdit').classList.remove('hide');$('sectionTitle').focus();}else if(toggle){const r=rows.find(x=>String(x.id)===toggle.dataset.sectionToggle);if(!r)return;const {error}=await sb.rpc('nalox_admin_sections_save',{p_id:r.id,p_section_key:r.section_key,p_title:r.title,p_subtitle:r.subtitle||'',p_icon:r.icon||'🏆',p_description:r.description,p_sort_order:r.sort_order||0,p_is_visible:toggle.dataset.visible!=='true'});if(error)return showModal('ERROR','SECTION UPDATE FAILED',error.message);await loadAdminManagedSections();await loadPublicManagedSections();}else if(del){const r=rows.find(x=>String(x.id)===del.dataset.sectionDelete);if(!r)return;confirmDelete('Delete section?',`<div><span>SECTION</span><b>${esc(r.title)}</b></div>`,async()=>{const {error}=await sb.rpc('nalox_admin_sections_delete',{p_id:r.id});if(error)return showModal('ERROR','SECTION DELETE FAILED',error.message);await loadAdminManagedSections();await loadPublicManagedSections();});}};

// Keep admin work/note sections refreshed whenever the admin panel is opened.
const _originalLoadAdmin=loadAdmin;
loadAdmin=async function(){await _originalLoadAdmin();await loadWorkAdmin();await loadAdminNotes();await loadAdminManagedSections()};

